/// Rename an opened object into an opened directory without replacing an entry.
///
/// This is a low-level native capability operation. The caller verifies owners,
/// access controls and recorded identities; it does not admit a private parent
/// or change the stricter policies of `PrivateDir` and `PrivateFile`. `directory`
/// specifies the source kind, and `name` must be exactly one normal component.
/// The source is reopened by its handle for synchronous DELETE access and its
/// identity is checked again. Neither parent nor source is reopened by pathname.
/// Native cross-volume or occupied-target failures have no copy/unlink fallback.
pub fn rename_by_handle_no_replace(
    source: impl AsHandle,
    parent: impl AsHandle,
    name: &OsStr,
    directory: bool,
) -> Result<()> {
    use std::os::windows::ffi::OsStrExt as _;
    if name.encode_wide().take(256).count() > 255
        || name.encode_wide().any(|c| matches!(c, 0 | 47 | 92))
    {
        return Err(Error::InvalidRelativePath);
    }
    let parts = RelativePath::new(Path::new(name))?;
    let [leaf] = parts.0.as_slice() else {
        return Err(Error::InvalidRelativePath);
    };
    let parent = parent.as_handle().try_clone_to_owned()?;
    nt::metadata(&parent, true, None)?;
    let source = nt::mutation_handle(source, directory)?;
    nt::rename_with_policy(&source, &parent, leaf, crate::Publication::CreateNew)
}

/// Mark an opened object for deletion without resolving its mutable pathname.
///
/// This low-level operation leaves owner, ACL and recorded-identity admission to
/// the caller, as with `rename_by_handle_no_replace`. The object is reopened by
/// handle for synchronous DELETE access and its identity is checked again.
/// A directory must be empty; no recursive or pathname deletion is attempted.
pub fn delete_by_handle(source: impl AsHandle, directory: bool) -> Result<()> {
    nt::delete(nt::mutation_handle(source, directory)?)
}

